  const createSubtask=(task:Task)=>{setForm({...blankForm,parent_task_id:task.id});setTemplateId("");setTemplateAsset(null);setSelected(null);setCreating(true);};
  const beginEdit=(task:Task)=>{const taskTypes=task.task_types?.length?task.task_types:[task.task_type];setForm({title:task.title,description:task.description||"",acceptance_criteria:task.acceptance_criteria||"",status:task.status,priority:task.priority,task_type:taskTypes[0],task_types:taskTypes,workstream:task.workstream,tags:task.tags||[],mod_targets:task.mod_targets||[],assigned_to:task.assigned_to||"",release_id:task.release_id||"",parent_task_id:task.parent_task_id||"",due_date:task.due_date?task.due_date.slice(0,10):"",blocked:task.blocked,blocker_reason:task.blocker_reason||""});setEditing(true);};
  const duplicateTask=(task:Task)=>{const taskTypes=task.task_types?.length?task.task_types:[task.task_type];setForm({title:`Copy of ${task.title}`,description:task.description||"",acceptance_criteria:task.acceptance_criteria||"",status:"intake",priority:task.priority,task_type:taskTypes[0],task_types:taskTypes,workstream:task.workstream,tags:task.tags||[],mod_targets:task.mod_targets||[],assigned_to:"",release_id:"",parent_task_id:task.parent_task_id||"",due_date:"",blocked:false,blocker_reason:""});setTemplateId("");setTemplateAsset(null);setSelected(null);setCreating(true);};
  const taskPayload=(version?:number)=>({...form,assigned_to:form.assigned_to||null,release_id:form.release_id||null,due_date:form.due_date?new Date(`${form.due_date}T12:00:00`).toISOString():null,position:selectedTask?.position||0,...(version!==undefined?{id:selectedTask?.id,version}: {})});
  const saveTask=async()=>{if(!selectedTask)return;const ok=await request("PATCH",taskPayload(selectedTask.version));if(ok){setEditing(false);setNotice({tone:"ok",text:"Task updated and recorded in its history."});}};
